                $(document).ready(function() {
                    $("#result").append("<div style='background:#fffce6;padding:0px 0px;text-align:center;color:#666666;'><form><div align='center' style='padding: 10px;height: 20px;'><div style='width: 100%;'><div class='fleft paddt4' style='width: 50%' align='right'>Your MobileShop profile will be logged in automatically!</div><div class='fleft paddt2 paddl10' align='left'><input checked='checked' id='staylogin' onchange='valueChanged();' type='checkbox'> Keep me logged in (Recommended).</div><div class='fleft paddt2  paddl5' align='left'><a href='javascript:void(0);' id='btnApprovepo' style='cursor:pointer;text-decoration:none;padding:2px 4px;display:none;' onclick='staypopup();' class='txt-hover primaryactbtn-medium clr6 boldtxt'>Submit</a></div><div class='fright' style='padding-top: 3px;' align='right'><a href=''><img src='https://imgs.mobileshopmatrimony.com/bmimgs/contextual-close-icon.png' height='14'/></a></div><div class='clear'></div></div></div></form></div>");
                });
                jStorage.set('MAILSTAYLOGIN', 1);
            }
            function valueChanged() {
                if ($('#staylogin').is(":checked"))
                    $("#btnApprovepo").hide();
                else
                    $("#btnApprovepo").show();
            }
            function staypopup() {
                var domain = 'marathi';
                staylogin_litebox("https://profile." + domain + "matrimony.com/template/staylogin.php");
                $("#cboxTopCenter,#cboxTopLeft,#cboxBottomCenter,#cboxBottomRight,#cboxBottomLeft,#cboxTopRight,#cboxTopCenter,#cboxTopLeft,#cboxMiddleLeft,#cboxMiddleRight").hide();
                $("#colorbox").focus();
                $("#cboxClose").hide();
                $("#cboxWrapper").focus();
            }
            function staylogin_litebox(url) {
                $.colorbox({
                    open: true,
                    opacity: 0.60,
                    open: true,
                    href: url
                });
            }
