                                            function EditPPAPICALL(reqobj) {
                                                $.ajax({
                                                    url: "//profile." + domainname + ".com/profiledetail/editppupdate.php",
                                                    type: 'POST',
                                                    data: reqobj['DATA'],
                                                    success: function(response) {
                                                        if (reqobj['CompType'] == 1) {
                                                            RefreshBlock(1);
                                                            //window.location.reload();
                                                        }
                                                    }
                                                });
                                            }
                                            function RefreshBlock(type) {
                                                var param = {
                                                    "MATRIID": MATRIID,
                                                    "EDITFORM": submitformtype,
                                                    "TYPE": type
                                                };
                                                if (type == 2) {
                                                    param.vpdata = $("#vpdata").val();
                                                }
                                                $.ajax({
                                                    url: "//profile." + domainname + ".com/profiledetail/ajaxeditpp.php",
                                                    type: 'POST',
                                                    data: param,
                                                    success: function(response) {
                                                        $('.modal').modal('hide');
                                                        setTimeout(function() {
                                                            $(".submitcls" + submitformtype).val("Submit");
                                                        }, 1000);
                                                        setTimeout(function() {
                                                            if (submitformtype >= 1 && submitformtype <= 9) {
                                                                if (type == 2) {
                                                                    $("#basicprefpopdiv").html(response);
                                                                } else {
                                                                    $("#basicprefdiv").html(response);
                                                                }
                                                            } else if (submitformtype >= 10 && submitformtype <= 15) {
                                                                //window.location.reload();
                                                                $("#religiousdiv").html(response);
                                                                //documentready();

                                                            } else if (submitformtype >= 16 && submitformtype <= 19) {
                                                                $("#pprofessionaldiv").html(response);
                                                            } else if (submitformtype >= 20 && submitformtype <= 25) {
                                                                $("#locationdiv").html(response);
                                                            } else if (submitformtype >= 26) {
                                                                $("#lookingfordiv").html(response);
                                                            }
                                                        }, 200);

                                                    }
                                                });
                                            }
                                            function modalclose(id, frmtype) {
                                                submitformtype = frmtype;
                                                console.log(submitformtype);
                                                RefreshBlock(2);
                                                setTimeout(function() {
                                                    $('#' + id).modal('hide');
                                                }, 1000);
                                                $('.collapse').collapse('hide');
                                                if (id == 'pp-matchcount') {
                                                    $(".submitcls" + submitformtype).val("Submit");
                                                }
                                            }
                                            // Location preference Start
                                            function checkboxSelect(self) {
                                                var PIGOTHRA = $("#PIGOTHRA").val();
                                                var val = $(self).val();
                                                var name = $(self).attr("name");
                                                $("#" + name.toLowerCase() + "err").hide();

                                                if ((val == '' || val == '0') || (name == 'GOTHRA' && val == '998')) {
                                                    var boolean = $(self).is(':checked') ? true : false;
                                                    ischecked(boolean, name)
                                                } else if (val != '' && val != '0') {
                                                    var tcnt = 0;
                                                    ischeckAll(name);
                                                    selectedtext(name);
                                                }
                                                if (name == 'EATINGHABITS' || name == 'DRINKING' || name == 'SMOKING' || name == 'STAR') {
                                                    checknonmandatory(name);
                                                }
                                            }

                                            function checknonmandatory(name) {
                                                var checkboxval = $("#" + name.toLowerCase() + "0").is(":checked");
                                                if (name.toLowerCase() == 'eatinghabits') {
                                                    if (checkboxval) {
                                                        document.getElementById("customCheck7_1").checked = false;
                                                        $('.customCheck7_box').css("display", "none");
                                                    } else if ($("#customCheck7").is(":checked")) {
                                                        $('.customCheck7_box').css("display", "block");
                                                    }
                                                } else if (name.toLowerCase() == 'drinking') {
                                                    if (checkboxval) {
                                                        document.getElementById("customCheck8_1").checked = false;
                                                        $('.customCheck8_box').css("display", "none");
                                                    } else if ($("#customCheck8").is(":checked")) {
                                                        $('.customCheck8_box').css("display", "block");
                                                    }
                                                } else if (name.toLowerCase() == 'smoking') {
                                                    if (checkboxval) {
                                                        document.getElementById("customCheck9_1").checked = false;
                                                        $('.customCheck9_box').css("display", "none");
                                                    } else if ($("#customCheck9").is(":checked")) {
                                                        $('.customCheck9_box').css("display", "block");
                                                    }
                                                } else if (name.toLowerCase() == 'star') {
                                                    if (checkboxval) {
                                                        document.getElementById("customCheck15_1").checked = false;
                                                        $('.customCheck15_box').css("display", "none");
                                                    } else if ($("#customCheck15").is(":checked")) {
                                                        $('.customCheck15_box').css("display", "block");
                                                    }
                                                } else if (name.toLowerCase() == 'subcaste') {
                                                    if ($("#subcaste_option_id_0").is(":checked") || !($("#customCheck12").is(":checked"))) {
                                                        document.getElementById("customCheck12_1").checked = false;
                                                        $('.customCheck12_box').css("display", "none");
                                                    } else if ($("#customCheck12").is(":checked")) {
                                                        $('.customCheck12_box').css("display", "block");
                                                    }
                                                } else if (name == 'MANGLIK') {
