                                            function suggestion(type) {
                                                var t = {
                                                    'sugstate': 'STATE',
                                                    'sugcity': 'CITY',
                                                    'sugedu': 'EDUCATION',
                                                    'sugcountry': 'COUNTRY'
                                                };
                                                var tmp = t[type] == 'EDUCATION' ? 'PPEDUCATION' : t[type];
                                                var ids = type == 'sugedu' ? selectedid(tmp, ',') : selectedid(tmp, ' ');

                                                if (type == 'sugcity') {
                                                    var hiddenval = $("#sugcityhidden").val();
                                                    if (hiddenval != '') {
                                                        hiddenval = hiddenval.replace(/~/g, " ");
                                                        ids += ' ' + hiddenval;
                                                    }
                                                }

                                                if (ids != '' && ids != '0') {
                                                    var htl = '';
                                                    //'<div class="carousel-inner" style="width: 90%;margin: 13px auto;padding-top: 18px;">';
                                                    //htl += '<div class="carousel-item active">';
                                                    DATA = 'ID=' + MATRIID + '&APPTYPE=300&KEYSEARCH=' + ids + '&KEYTYPE=' + t[type];
                                                    if (type == 'sugcity') {
                                                        DATA += '&GENTYPE=F';
                                                    } else if (type == 'sugcountry') {
                                                        DATA += '&PICOUNTRY=' + PICOUNTRY;
                                                    }
                                                    $.ajax({
                                                        url: "https://api.mobileshopmatrimony.com/appeditprofile/appgetsuggestionslist.php",
                                                        type: 'POST',
                                                        data: DATA,
                                                        success: function(response) {
                                                            if (response['SEARCHRESULT']) {
                                                                let t = 0;
                                                                for (const k in response.SEARCHRESULT) {
                                                                    if (type == 'sugstate')
                                                                        htl += '<div class="swiper-slide" onclick="suggeststate(' + k + ',this);">' + response.SEARCHRESULT[k] + '</div>';
                                                                    else if (type == 'sugcity')
                                                                        htl += '<div class="swiper-slide" onclick="suggestcity(' + k + ',this);">' + response.SEARCHRESULT[k] + '</div>';
                                                                    else if (type == 'sugedu')
                                                                        htl += '<div class="swiper-slide" onclick="suggestedu(' + k + ',this);">' + response.SEARCHRESULT[k] + '</div>';
                                                                    else if (type == 'sugcountry')
                                                                        htl += '<div class="swiper-slide" onclick="suggestcountry(' + k + ',this);">' + response.SEARCHRESULT[k] + '</div>';
                                                                    t++;
                                                                }
                                                                if (t < 5) {
                                                                    $(".swiper-button-next").hide();
                                                                    $(".swiper-button-prev").hide();
                                                                } else {
                                                                    $(".swiper-button-next").show();
                                                                    $(".swiper-button-prev").show();
                                                                }
                                                                //htl += '</div>';
                                                                //htl += '</div>';
                                                                //htl += '<a class="carousel-control-prev" href="#'+type+'" data-slide="prev"><img src="//imgs.mobileshopmatrimony.com/bmimgs/desktop-images/left-arrow-pp.svg" style="position: absolute;margin-top: 20px;margin-left: -60px;"></a><a class="carousel-control-next" href="#'+type+'" data-slide="next"><img src="//imgs.mobileshopmatrimony.com/bmimgs/desktop-images/right-arrow-pp.svg" style="position: absolute;margin-top: 20px;margin-left: 44px;"></a>';
                                                                $("#" + type).html(htl);
                                                                setTimeout(function() {
                                                                    swipertrigger();
                                                                }, 1000);
                                                                if (type == 'sugcountry') {
                                                                    if (t > 1) {
                                                                        $("#div" + type).html('Suggested Countries:');
                                                                    } else {
                                                                        $("#div" + type).html('Suggested Country:');
                                                                    }
                                                                }
                                                                $("#div" + type).show();
                                                            } else {
                                                                $("#div" + type).hide();
                                                            }
                                                        }
                                                    });
                                                } else {
                                                    $("#" + type).html('');
                                                    $("#div" + type).hide();
                                                }
                                            }
                                            function suggeststate(k, self) {
                                                $(self).addClass('active-suggested');
                                                $(self).fadeOut(1000);
                                                setTimeout(function() {
                                                    suggestclick(k, 'STATE', '');
                                                }, 1000);
                                            }
                                            function suggestcity(k, self) {
                                                $(self).addClass('active-suggested');
                                                $(self).fadeOut(1000);
                                                var ttxt = $(self).text();
                                                setTimeout(function() {
                                                    suggestclick(k, 'CITY', ttxt);
                                                }, 1000);
                                            }
                                            function suggestedu(k, self) {
                                                $(self).addClass('active-suggested');
                                                $(self).fadeOut(1000);
                                                setTimeout(function() {
                                                    suggestclick(k, 'MOREEDUCATIONRIGHTID', '');
                                                }, 1000);
                                            }
                                            function suggestcountry(k, self) {
                                                $(self).addClass('active-suggested');
                                                $(self).fadeOut(1000);
                                                setTimeout(function() {
                                                    suggestclick(k, 'COUNTRY', '')
                                                }, 1000);
                                            }
                                            function suggestclick(k, name, ttxt) {
                                                if (name == 'MOREEDUCATIONRIGHTID') {
                                                    key = name + k;
                                                } else {
                                                    key = name.toLowerCase() + k;
                                                }
                                                console.log("ttttttttttttttttttttttttttttttttttttttttttttt")
                                                console.log(key)
                                                console.log($("#" + key).length)
                                                if ($("#" + key).length > 0) {
                                                    console.log("========================================")
                                                    dgebid(key).checked = true;
                                                    //$("#"+key).attr("checked",true);
                                                    selectedtext(name);
                                                } else if (name == 'CITY') {

                                                    var hval = $("#sugcityhidden").val();
                                                    hval += k + '~';
                                                    console.log("*************************************")
                                                    console.log(name)
                                                    console.log(k)

                                                    $("#sugcityhidden").val(hval);
                                                    var htxt = $("#citylbl").text();
                                                    console.log("^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^")
                                                    console.log(htxt)
                                                    console.log(ttxt);
                                                    $("#citylbl").text(ttxt + ',' + htxt);

                                                }
                                            }
                                            function selectedTextBold(name) {
                                                name = name == 'MOREEDUCATIONRIGHTID' ? 'PPEDUCATION' : name;
                                                $("input[name='" + name + "']").each(function() {
                                                    if ($(this).is(':checked')) {
                                                        $(this).next('label').addClass('fw-bold');
                                                    } else {
                                                        $(this).next('label').removeClass('fw-bold');
                                                    }
                                                })
                                            }
                                            function selectedtext(name) {
                                                var txt = '';
                                                name = name == 'MOREEDUCATIONRIGHTID' ? 'PPEDUCATION' : name;
                                                name = name == 'PPEDUCATION' ? 'EDUCATIONRIGHT' : name;
                                                $("input[name='" + name + "']").each(function() {
                                                    if ($(this).is(':checked')) {
                                                        if ($(this).next('label').text() == 'Any') {
                                                            txt = 'Any, ';
                                                            return false;
                                                        } else if ($(this).next('label').text() == 'Hindi-All') {
                                                            txt = 'Hindi-All, ';
                                                            return false;
                                                        } else if ($(this).next('label').text() == 'Doesn\'t matter') {
                                                            txt = 'Doesn\'t matter, ';
                                                            return false;
                                                        } else if ($(this).next('label').text() == 'All except my gothra') {
                                                            txt = 'All except my gothra, ';
                                                            return false;
                                                        } else
                                                            txt += $(this).next('label').text() + ', ';
                                                    }
                                                });
                                                if (name == 'MAINCASTECLUSTER[]') {
                                                    if ($("#clustercaste_option_id_0").is(':checked')) {
                                                        txt = 'Any, ';
                                                    }
                                                }
                                                if (name == 'PPEDUCATION' || name == 'MOREEDUCATIONRIGHTID' || name == 'EDUCATIONRIGHT') {
                                                    name1 = 'moreeducationrightid';
                                                } else if (name == 'MAINCASTECLUSTER[]') {
                                                    name1 = 'caste';
                                                } else if (name == 'SUBCASTE[]') {
                                                    if ($("#subcaste_option_id_0").is(':checked')) {
                                                        txt = 'Any, ';
                                                    }
                                                    name1 = 'subcaste';
                                                } else if (name == 'MANGLIK_PP') {
                                                    name1 = 'manglik';
                                                } else if (name == 'OCCUPATIONRIGHT') {
                                                    name1 = 'occupation';
                                                } else {
                                                    name1 = name.toLowerCase();
                                                }
                                                txt = txt.slice(0, -2);
                                                $("#" + name1 + 'lbl').html(txt);
                                                $("#" + name1 + "-rm").hide();
                                                console.log(name)
                                                if (name == 'STATE')
                                                    suggestion('sugstate');
                                                else if (name == 'CITY')
                                                    suggestion('sugcity');
                                                else if (name == 'PPEDUCATION')
                                                    suggestion('sugedu');
                                                else if (name == 'COUNTRY') {
                                                    if (PIGENDER == 'M' && PICOUNTRY != '98')
                                                        suggestion('sugcountry');
                                                } else if (name1 = 'manglik' && txt == 'Yes') {
                                                    selectedtext('MANGLIK_PP');
                                                } else if (name == 'PHYSICALSTATUS' || name == 'HAVECHILDREN') {
                                                    $('.collapse').collapse('hide');
                                                }
                                                selectedTextBold(name);
                                            }
                                            function selectedid(selid, devider) {
