                                            function commonSearch(id) {
                                                var input, filter, ul, li, a, i;
                                                input = document.getElementById("searchinput_" + id);
                                                filter = input.value.toUpperCase();
                                                div = document.getElementById("searchcontent_" + id);
                                                a = div.getElementsByClassName("searchtag");
                                                for (i = 0; i < a.length; i++) {
                                                    l = a[i].getElementsByTagName("label")[0];
                                                    txtValue = l.textContent || l.innerText;
                                                    if (txtValue.toUpperCase().indexOf(filter) > -1) {
                                                        a[i].style.display = "";
                                                    } else {
                                                        a[i].style.display = "none";
                                                    }
                                                }
                                            }
                                            function swipertrigger() {
                                                const swiper = new Swiper('.swiper-container',{
                                                    // Optional parameters
