                                            /** Window scroll enable and disable */
                                            // left: 37, up: 38, right: 39, down: 40,
                                            // spacebar: 32, pageup: 33, pagedown: 34, end: 35, home: 36
                                            var keys = {
                                                37: 1,
                                                38: 1,
                                                39: 1,
                                                40: 1
                                            };

                                            function preventDefault(e) {
                                                e.preventDefault();
                                            }

                                            function preventDefaultForScrollKeys(e) {
                                                if (keys[e.keyCode]) {
                                                    preventDefault(e);
                                                    return false;
                                                }
                                            }

                                            // modern Chrome requires { passive: false } when adding event
                                            var supportsPassive = false;
                                            try {
                                                window.addEventListener("test", null, Object.defineProperty({}, 'passive', {
                                                    get: function() {
                                                        supportsPassive = true;
                                                    }
                                                }));
                                            } catch (e) {}

                                            var wheelOpt = supportsPassive ? {
                                                passive: false
                                            } : false;
                                            var wheelEvent = 'onwheel'in document.createElement('div') ? 'wheel' : 'mousewheel';

                                            // call this to Disable
                                            function disableScroll() {
                                                window.addEventListener('DOMMouseScroll', preventDefault, false);
                                                // older FF
                                                window.addEventListener(wheelEvent, preventDefault, wheelOpt);
                                                // modern desktop
                                                window.addEventListener('touchmove', preventDefault, wheelOpt);
                                                // mobile
                                                window.addEventListener('keydown', preventDefaultForScrollKeys, false);
                                            }

                                            // call this to Enable
                                            function enableScroll() {
                                                window.removeEventListener('DOMMouseScroll', preventDefault, false);
                                                window.removeEventListener(wheelEvent, preventDefault, wheelOpt);
                                                window.removeEventListener('touchmove', preventDefault, wheelOpt);
                                                window.removeEventListener('keydown', preventDefaultForScrollKeys, false);
                                            }

                                            /**
* Dropdown Cuestom Design Apply Start
*/
                                            var dropselected = {
                                                'STAGE': 0
                                            };
                                            function dropdowncustom(clsname) {
                                                var x, i, j, l, ll, selElmnt, a, b, c;
                                                /* Look for any elements with the class "custom-select": */
                                                x = document.getElementsByClassName(clsname);
                                                l = x.length;
                                                for (i = 0; i < l; i++) {
                                                    selElmnt = x[i].getElementsByTagName("select")[0];
                                                    ll = selElmnt.length;
                                                    /* For each element, create a new DIV that will act as the selected item: */
                                                    a = document.createElement("DIV");
                                                    a.setAttribute("class", "select-selected");
                                                    a.innerHTML = selElmnt.options[selElmnt.selectedIndex].innerHTML;
                                                    x[i].appendChild(a);
                                                    /* For each element, create a new DIV that will contain the option list: */
                                                    b = document.createElement("DIV");
                                                    b.setAttribute("class", "select-items select-hide select-items-scroll");
                                                    b.setAttribute("id", "select-items-" + selElmnt.name);

                                                    //   b1 = document.createElement("DIV");
                                                    //   b1.setAttribute("class", "select-items-scroll");
                                                    //   b.appendChild(b1);

                                                    for (j = 1; j < ll; j++) {
                                                        /* For each option in the original select element,
        create a new DIV that will act as an option item: */
                                                        c = document.createElement("DIV");
                                                        c.innerHTML = selElmnt.options[j].innerHTML;
                                                        if (selElmnt.options[j].selected) {
                                                            c.setAttribute("class", "same-as-selected");
                                                            dropselected[selElmnt.name] = j;
                                                        }
                                                        // if(selElmnt.name == 'STAGE') {
                                                        //     c.setAttribute("onclick", "ppValidateAge('','','','byfrom',1);");
                                                        // }
                                                        // else if(selElmnt.name == 'ENAGE') {
                                                        //     c.setAttribute("onclick", "ppValidateAge('','','','byto');");
                                                        // }
                                                        c.addEventListener("click", function(e) {
                                                            /* When an item is clicked, update the original select box,
            and the selected item: */
                                                            var y, i, k, s, h, sl, yl;
                                                            s = this.parentNode.parentNode.getElementsByTagName("select")[0];
                                                            sl = s.length;
                                                            h = this.parentNode.previousSibling;
                                                            for (i = 0; i < sl; i++) {
                                                                if (s.options[i].innerHTML == this.innerHTML) {
                                                                    s.selectedIndex = i;
                                                                    h.innerHTML = this.innerHTML;
                                                                    y = this.parentNode.getElementsByClassName("same-as-selected");
                                                                    yl = y.length;
                                                                    for (k = 0; k < yl; k++) {
                                                                        y[k].removeAttribute("class");
                                                                    }
                                                                    this.setAttribute("class", "same-as-selected");
                                                                    break;
                                                                }
                                                            }
                                                            h.click();
                                                            console.log(s.name)
                                                            if (s.name == 'STAGE') {
                                                                $("#ENAGE").nextAll('div').slice(0, 2).remove();
                                                                $(s).trigger("change");
                                                                dropdowncustom('custom-select-eage');
                                                            } else if (s.name == 'ENAGE') {
                                                                dgebid("ageerr").innerHTML = '';
                                                                $(s).trigger("change");
                                                            } else if (s.name == 'FROMFEET') {
                                                                $("#TOFEET").nextAll('div').slice(0, 2).remove();
                                                                $(s).trigger("change");
                                                                dropdowncustom('custom-select-eheight');
                                                            } else if (s.name == 'TOFEET') {
                                                                $("#FROMFEET").nextAll('div').slice(0, 2).remove();
                                                                $(s).trigger("change");
                                                                dropdowncustom('custom-select-fheight');
                                                            } else if (s.name == 'STANNUALINCOME') {
                                                                $("#ENDANNUALINCOME").nextAll('div').slice(0, 2).remove();
                                                                $(s).trigger("change");
                                                                dropdowncustom('custom-select-eincome');
                                                            } else if (s.name == 'ENDANNUALINCOME') {
                                                                $("#STANNUALINCOME").nextAll('div').slice(0, 2).remove();
                                                                $(s).trigger("change");
                                                                dropdowncustom('custom-select-fincome');
                                                            }
                                                        });
                                                        b.appendChild(c);
                                                    }
                                                    x[i].appendChild(b);
                                                    a.addEventListener("click", function(e) {
                                                        console.log("DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD")
                                                        /* When the select box is clicked, close any other select boxes,
        and open/close the current select box: */
                                                        e.stopPropagation();
                                                        closeAllSelect(this);
                                                        this.nextSibling.classList.toggle("select-hide");
                                                        this.classList.toggle("select-arrow-active");
                                                        // if(!this.nextSibling.classList.contains("select-hide")) {
                                                        //     console.log("UUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUUU")
                                                        // }
                                                    });
                                                }
                                            }
                                            function closeAllSelect(elmnt) {
                                                /* A function that will close all select boxes in the document,
  except the current select box: */
                                                var x, y, i, xl, yl, arrNo = [];
                                                x = document.getElementsByClassName("select-items");
                                                y = document.getElementsByClassName("select-selected");
                                                xl = x.length;
                                                yl = y.length;
                                                for (i = 0; i < yl; i++) {
                                                    if (elmnt == y[i]) {
                                                        arrNo.push(i)
                                                    } else {
                                                        y[i].classList.remove("select-arrow-active");
                                                    }
                                                }
                                                for (i = 0; i < xl; i++) {
                                                    if (arrNo.indexOf(i)) {
                                                        x[i].classList.add("select-hide");
                                                    }
                                                }
                                            }

                                            /* If the user clicks anywhere outside the select box,
then close all select boxes: */
                                            document.addEventListener("click", closeAllSelect);
                                            dropdowncustom("custom-select-religion");
                                            dropdowncustom("custom-select-fage");
                                            dropdowncustom("custom-select-eage");
                                            dropdowncustom("custom-select-fheight");
                                            dropdowncustom("custom-select-eheight");
                                            dropdowncustom("custom-select-fincome");
                                            dropdowncustom("custom-select-eincome");

